import { useLocation, useSearch } from "wouter";
import { Mail, ArrowRight, Sparkles } from "lucide-react";
import { useAuth } from "@/hooks/use-auth";
import { Button } from "@/components/ui/button";

export default function Auth() {
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  const search = useSearch();

  const params = new URLSearchParams(search);
  const mode = params.get("mode") || "signup";
  const isSignInMode = mode === "signin";

  if (user) {
    setLocation("/home", { replace: true });
    return null;
  }

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden">
      {/* Background gradient orbs */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-brand/20 rounded-full blur-3xl animate-pulse" />
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-brand/10 rounded-full blur-3xl animate-pulse" style={{ animationDelay: "1s" }} />
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-brand/5 rounded-full blur-3xl" />
      </div>

      <div className="w-full max-w-md mx-auto px-4 relative z-10">
        {/* Logo / Brand */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full border border-border/50 bg-card/50 backdrop-blur-sm mb-6">
            <Sparkles className="h-4 w-4 text-brand" />
            <span className="text-xs font-medium text-muted-foreground">Artificial Gateway</span>
          </div>
          <h1 className="text-4xl font-bold tracking-tight bg-gradient-to-br from-foreground to-foreground/70 bg-clip-text">
            {isSignInMode ? "Welcome back" : "Create your account"}
          </h1>
          <p className="text-muted-foreground mt-3 text-base">
            {isSignInMode
              ? "Sign in to access your gateway"
              : "Start building with AI in minutes"}
          </p>
        </div>

        {/* Card */}
        <div className="rounded-2xl border border-border/50 bg-card/80 backdrop-blur-xl p-8 shadow-2xl shadow-black/10">
          {/* Google OAuth */}
          <a
            href="/auth/google?redirect=/home"
            className="group flex items-center justify-center gap-3 w-full px-5 py-3.5 rounded-xl border border-border/60 bg-background/50 text-sm font-medium hover:bg-accent/50 hover:border-border transition-all duration-200"
          >
            <svg className="h-5 w-5 shrink-0" viewBox="0 0 24 24" aria-hidden>
              <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4" />
              <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
              <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
              <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
            </svg>
            Continue with Google
            <ArrowRight className="h-4 w-4 opacity-0 -translate-x-1 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-200" />
          </a>

          {/* Divider */}
          <div className="relative my-6">
            <div className="absolute inset-0 flex items-center">
              <span className="w-full border-t border-border/50" />
            </div>
            <div className="relative flex justify-center text-xs uppercase">
              <span className="bg-card/80 px-3 text-muted-foreground tracking-wider">or</span>
            </div>
          </div>

          {/* Email buttons */}
          <div className="space-y-3">
            {isSignInMode ? (
              <Button
                onClick={() => setLocation("/auth/login")}
                className="w-full h-12 text-sm font-medium rounded-xl bg-brand hover:bg-brand/90 transition-all duration-200 shadow-lg shadow-brand/20"
              >
                <Mail className="h-4 w-4 mr-2" />
                Sign in with Email
              </Button>
            ) : (
              <Button
                onClick={() => setLocation("/")}
                className="w-full h-12 text-sm font-medium rounded-xl bg-brand hover:bg-brand/90 transition-all duration-200 shadow-lg shadow-brand/20"
              >
                <Mail className="h-4 w-4 mr-2" />
                Sign up with Email
              </Button>
            )}
          </div>

          {/* Mode toggle */}
          <div className="mt-6 text-center">
            <button
              type="button"
              onClick={() => setLocation(isSignInMode ? "/auth?mode=signup" : "/auth?mode=signin")}
              className="text-sm text-muted-foreground hover:text-foreground transition-colors duration-200"
            >
              {isSignInMode ? (
                <>Don't have an account? <span className="font-medium text-foreground">Sign up</span></>
              ) : (
                <>Already have an account? <span className="font-medium text-foreground">Sign in</span></>
              )}
            </button>
          </div>
        </div>

        {/* Footer text */}
        <p className="text-center text-xs text-muted-foreground mt-6">
          By continuing, you agree to our{" "}
          <a href="/terms" className="underline hover:text-foreground transition-colors">Terms</a>
          {" "}and{" "}
          <a href="/privacy" className="underline hover:text-foreground transition-colors">Privacy Policy</a>
        </p>
      </div>
    </div>
  );
}

