import { useState } from "react";
import { motion } from "framer-motion";
import { Check, ArrowUpRight, Zap, Shield, Building2, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Link } from "wouter";
import {
  Accordion, AccordionContent, AccordionItem, AccordionTrigger,
} from "@/components/ui/accordion";
import {
  Container,
  Section,
  PageHeader,
} from "@/components/system";

const tiers = [
  {
    name: "Free",
    monthlyPrice: "Pay-as-you-go",
    yearlyPrice: "Pay-as-you-go",
    description: "For personal projects and exploration.",
    icon: Zap,
    features: [
      { text: "Standard rate limits", included: true },
      { text: "Community support", included: true },
      { text: "Standard latency routing", included: true },
      { text: "Access to basic models", included: true },
      { text: "5% routing fee", included: true },
      { text: "Priority support", included: false },
      { text: "Custom SLAs", included: false },
    ],
    cta: "Get Started Free",
    popular: false,
  },
  {
    name: "Max",
    monthlyPrice: "$10",
    yearlyPrice: "$5",
    monthlyLabel: "/month",
    yearlyLabel: "/month",
    description: "For developers scaling their applications.",
    icon: Sparkles,
    badge: "50% off annual",
    features: [
      { text: "Higher rate limits", included: true },
      { text: "Priority latency routing", included: true },
      { text: "Access to all models", included: true },
      { text: "Email support", included: true },
      { text: "Zero routing fees", included: true },
      { text: "Advanced analytics", included: true },
      { text: "Custom SLAs", included: false },
    ],
    cta: "Start Free Trial",
    popular: true,
  },
  {
    name: "Enterprise",
    monthlyPrice: "Custom",
    yearlyPrice: "Custom",
    description: "For teams with high volume and specific needs.",
    icon: Building2,
    features: [
      { text: "Everything in Max", included: true },
      { text: "Volume discounts", included: true },
      { text: "Dedicated account manager", included: true },
      { text: "Custom SLAs", included: true },
      { text: "SSO & advanced access control", included: true },
      { text: "On-premise deployment", included: true },
      { text: "24/7 phone support", included: true },
    ],
    cta: "Contact Sales",
    popular: false,
  },
];

const comparisonFeatures = [
  { name: "Rate limits", free: "Standard", max: "High", enterprise: "Custom" },
  { name: "Latency routing", free: "Standard", max: "Priority", enterprise: "Custom" },
  { name: "Models", free: "Basic", max: "All", enterprise: "All" },
  { name: "Support", free: "Community", max: "Email", enterprise: "24/7 Phone" },
  { name: "Routing fee", free: "5%", max: "0%", enterprise: "0%" },
  { name: "Analytics", free: "Basic", max: "Advanced", enterprise: "Custom" },
  { name: "SLAs", free: "-", max: "-", enterprise: "Custom" },
  { name: "SSO", free: "-", max: "-", enterprise: "✓" },
];

const testimonials = [
  {
    quote: "Switching to this gateway reduced our LLM costs by 40% while improving reliability.",
    author: "Sarah Chen",
    role: "CTO, TechFlow",
  },
  {
    quote: "The unified API saved us weeks of integration work across multiple providers.",
    author: "Michael Torres",
    role: "Lead Engineer, DataPulse",
  },
  {
    quote: "Enterprise support has been exceptional. They understand our compliance requirements.",
    author: "Emily Rodriguez",
    role: "VP Engineering, SecureAI",
  },
];

const faqs = [
  {
    q: "Do you mark up provider pricing?",
    a: "No. We pass the exact token cost directly to you. The Free plan includes a 5% routing fee, and the Max plan has no routing fees. We aim to reduce routing fees in the future.",
  },
  {
    q: "Can I bring my own API keys?",
    a: "Yes. If you add your own API keys for providers in the dashboard, routing fees are waived on all plans.",
  },
  {
    q: "How are streaming costs calculated?",
    a: "Based on the total number of input and output tokens consumed, same as standard requests.",
  },
  {
    q: "What if a provider goes down?",
    a: "We automatically retry using the next available provider with equivalent capabilities.",
  },
  {
    q: "Is there a free trial for Max?",
    a: "Yes. All new accounts get a 14-day free trial of Max with full access to all features. No credit card required to start.",
  },
  {
    q: "How do I upgrade to Enterprise?",
    a: "Contact our sales team for a custom quote. We'll work with your team to understand your requirements and provide a tailored solution.",
  },
];

export default function Pricing() {
  const [annual, setAnnual] = useState(false);

  return (
    <div className="flex-1">
      <motion.div
        initial={{ opacity: 0, y: 12 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3, ease: "easeOut" }}
      >
        <PageHeader
          eyebrow="Pricing"
          title="Transparent pricing."
          subtitle="You pay the exact API cost of the underlying provider, plus a small routing fee. Zero lock-in."
        />
      </motion.div>

      <Section size="default" className="pt-4 md:pt-6">
        <Container>
          <div className="mx-auto max-w-3xl">
            <div className="flex items-center justify-center gap-3 mb-10">
              <span className={cn("text-sm font-medium", !annual ? "text-foreground" : "text-muted-foreground")}>
                Monthly
              </span>
              <button
                onClick={() => setAnnual(!annual)}
                className={cn(
                  "relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ease-in-out focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
                  annual ? "bg-primary" : "bg-muted"
                )}
              >
                <span
                  className={cn(
                    "pointer-events-none inline-block h-5 w-5 rounded-full bg-background shadow-lg ring-0 transition duration-200 ease-in-out",
                    annual ? "translate-x-5" : "translate-x-0"
                  )}
                />
              </button>
              <span className={cn("text-sm font-medium", annual ? "text-foreground" : "text-muted-foreground")}>
                Annual
                <span className="ml-1.5 inline-flex items-center rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                  Save 50%
                </span>
              </span>
            </div>

            <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
              {tiers.filter((_, i) => i !== 1).map((tier, index) => {
                const Icon = tier.icon;
                return (
                  <motion.div
                    key={tier.name}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4, delay: index * 0.1 }}
                    className={cn(
                      "relative flex flex-col rounded-xl border bg-card p-6 transition-all",
                      tier.popular
                        ? "border-primary shadow-lg scale-[1.02]"
                        : "border-border hover:border-muted-foreground/30"
                    )}
                  >
                    {tier.popular && (
                      <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                        <span className="inline-flex items-center rounded-full bg-primary px-3 py-1 text-[10px] font-medium uppercase tracking-wider text-primary-foreground">
                          Most Popular
                        </span>
                      </div>
                    )}

                    <div className="mb-4">
                      <div className="mb-3 flex items-center gap-2">
                        <div className={cn(
                          "flex h-8 w-8 items-center justify-center rounded-lg",
                          tier.popular ? "bg-primary/10" : "bg-muted"
                        )}>
                          <Icon className={cn("h-4 w-4", tier.popular ? "text-primary" : "text-muted-foreground")} />
                        </div>
                        <h3 className="text-sm font-semibold">{tier.name}</h3>
                        {tier.badge && (
                          <span className="rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
                            {tier.badge}
                          </span>
                        )}
                      </div>

                      <div className="flex items-baseline gap-1">
                        <span className="text-3xl font-bold tracking-tight">
                          {annual ? tier.yearlyPrice : tier.monthlyPrice}
                        </span>
                        {(annual ? tier.yearlyLabel : tier.monthlyLabel) && (
                          <span className="text-sm text-muted-foreground">
                            {annual ? tier.yearlyLabel : tier.monthlyLabel}
                          </span>
                        )}
                      </div>
                      <p className="mt-2 text-sm text-muted-foreground">{tier.description}</p>
                    </div>

                    <ul className="mb-6 flex-1 space-y-3">
                      {tier.features.map((feature) => (
                        <li key={feature.text} className="flex items-start gap-2">
                          <Check
                            className={cn(
                              "mt-0.5 h-4 w-4 shrink-0",
                              feature.included ? "text-primary" : "text-muted-foreground/50"
                            )}
                          />
                          <span className={cn(
                            "text-sm",
                            !feature.included && "text-muted-foreground"
                          )}>
                            {feature.text}
                          </span>
                        </li>
                      ))}
                    </ul>

                    <Button
                      asChild
                      className={cn("w-full", tier.popular && "shadow-md")}
                      variant={tier.popular ? "default" : "outline"}
                    >
                      <Link href={tier.name === "Enterprise" ? "/contact" : "/auth?mode=signup"}>
                        {tier.cta}
                        <ArrowUpRight className="h-4 w-4" />
                      </Link>
                    </Button>
                  </motion.div>
                );
              })}
            </div>
          </div>
        </Container>
      </Section>

      <Section divider="top" size="default" className="px-6 md:px-20">
        <div className="mx-auto max-w-4xl">
          <h3 className="mb-8 text-center text-base font-bold tracking-tight">
            Compare all features
          </h3>
          <div className="rounded-xl border border-border bg-card overflow-hidden">
            <div className="grid grid-cols-4 border-b border-border bg-muted/50">
              <div className="p-4 text-sm font-medium">Feature</div>
              <div className="p-4 text-center text-sm font-medium">Free</div>
              <div className="p-4 text-center text-sm font-medium">Max</div>
              <div className="p-4 text-center text-sm font-medium">Enterprise</div>
            </div>
            {comparisonFeatures.map((feature, i) => (
              <div
                key={feature.name}
                className={cn(
                  "grid grid-cols-4",
                  i < comparisonFeatures.length - 1 && "border-b border-border"
                )}
              >
                <div className="p-4 text-sm">{feature.name}</div>
                <div className="p-4 text-center text-sm text-muted-foreground">{feature.free}</div>
                <div className="p-4 text-center text-sm text-muted-foreground">{feature.max}</div>
                <div className="p-4 text-center text-sm text-muted-foreground">{feature.enterprise}</div>
              </div>
            ))}
          </div>
        </div>
      </Section>

      <Section divider="top" size="default" className="px-6 md:px-20 bg-muted/30">
        <div className="mx-auto max-w-5xl">
          <h3 className="mb-8 text-center text-base font-bold tracking-tight">
            Trusted by teams building with every major provider
          </h3>
          <div className="grid gap-6 md:grid-cols-3">
            {testimonials.map((testimonial, i) => (
              <motion.div
                key={i}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.4, delay: i * 0.1 }}
                className="rounded-xl border border-border bg-card p-6"
              >
                <p className="mb-4 text-sm leading-relaxed text-muted-foreground">
                  "{testimonial.quote}"
                </p>
                <div>
                  <p className="text-sm font-medium">{testimonial.author}</p>
                  <p className="text-xs text-muted-foreground">{testimonial.role}</p>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </Section>

      <Section divider="top" className="px-6 md:px-20 py-16 md:py-20">
        <div className="mx-auto max-w-3xl">
          <h3 className="mb-8 text-center text-base font-bold tracking-tight">
            Frequently Asked Questions
          </h3>
          <Accordion type="single" collapsible>
            {faqs.map((item, i) => (
              <AccordionItem key={i} value={`item-${i}`}>
                <AccordionTrigger className="text-[15px] font-medium">
                  {item.q}
                </AccordionTrigger>
                <AccordionContent className="text-[15px] leading-[200%] text-muted-foreground">
                  {item.a}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      </Section>

      <section className="border-t border-border px-6 md:px-20 py-16 md:py-20">
        <div className="mx-auto max-w-2xl text-center">
          <h3 className="text-xl font-bold tracking-tight">Ready to get started?</h3>
          <p className="mt-3 text-[15px] leading-[200%] text-muted-foreground">
            Join thousands of teams using our gateway to access every major LLM provider with zero vendor lock-in.
          </p>
          <div className="mt-6 flex flex-col gap-3 sm:flex-row sm:justify-center">
            <Button asChild>
              <Link href="/auth?mode=signup">
                Start building free
                <ArrowUpRight className="h-4 w-4" />
              </Link>
            </Button>
            <Button variant="outline" asChild>
              <Link href="/contact">Talk to sales</Link>
            </Button>
          </div>
        </div>
      </section>
    </div>
  );
}

